    fn receive_message_defaults_to_one_message() {
        let line = r#"{"Command": "ReceiveMessage", "QueueName": "q", "Extra": 1}"#;
        assert_eq!(
            parse(line.as_bytes()),
            Ok(Command::ReceiveMessage {
                queue: "q".to_owned(),
                max_messages: 1,
                visibility_timeout: None,
            })
        );
    }
}
