        assert_eq!(code(line), ErrorCode::QueueNameInvalid);
    }

    #[test]
    fn attributes_must_be_an_object_with_known_valid_members() {
        let cases = [
            r#""x""#,
            r#"{"Bogus": 1}"#,
            r#"{"VisibilityTimeout": 43201}"#,
            r#"{"RetentionSeconds": 59}"#,
