            // configured dead-letter queue always exists.
            let target = self
                .queues
                .get_mut(&target)
                .expect("a configured dead-letter queue exists");
            for message in received.dead {
                target.enqueue_dead(message);
            }
            target.expire(now);
        }
        Ok(Output::Received {
            messages: received.delivered,
        })
    }

