            r#"{"Command":"CreateQueue","QueueName":"a","Attributes":{"MaxReceiveCount":3}}"#,
            r#"{"Command":"CreateQueue","QueueName":"a","Attributes":{"DeadLetterQueue":"d","MaxReceiveCount":3}}"#,
